import test from 'node:test';import assert from 'node:assert/strict';
import{evaluatePreview,CANDIDATES}from'./model.js';
test('preview measures the real current shading gap without inventing a proposed score',()=>{const a=evaluatePreview(),b=evaluatePreview({underneath:false});assert.equal(a.baseline.delta,2);assert.equal(a.baseline.effects.length,1);assert(a.shared.ledger.some(x=>x.id==='underneath'));assert(!b.shared.ledger.some(x=>x.id==='underneath'));assert.equal(a.score,undefined);});
test('existing stunt geometry detects Texas/contain conflicts and leaves Tom edges available',()=>{assert.equal(evaluatePreview({stunt:'texas'}).conflicts.length,2);assert.equal(evaluatePreview({stunt:'left_tom'}).conflicts.length,0);assert.equal(evaluatePreview({contain:false}).conflicts.length,0);});
test('custom responsibility changes stay consistent across every proposed surface',()=>{const a=evaluatePreview({manOverride:true});assert.equal(a.shared.insideZones,1);for(const surface of Object.values(a.projections)){assert.equal(surface.assignments,a.shared.assignments);assert.equal(surface.ledger,a.shared.ledger);assert.equal(surface.deepZones,3);}assert.equal(evaluatePreview({manOverride:false}).shared.insideZones,2);});
test('variation candidates exist in the chosen playbook formation; no disguise success is fabricated',()=>{const x=evaluatePreview();assert.equal(x.candidates.length,3);for(const c of x.candidates){assert(CANDIDATES.includes(c.name));assert(c.play);assert.equal(c.disguiseVerified,undefined);}});
test('all review input combinations retain eleven players and valid shared projections',()=>{let count=0;for(const underneath of [true,false])for(const stunt of ['none','texas','left_tom'])for(const contain of [true,false])for(const manOverride of [true,false])for(const rpo of ['bubble','glance'])for(const execution of ['simple','comfortable','advanced']){const x=evaluatePreview({underneath,stunt,contain,manOverride,rpo,execution});assert.equal(x.shared.assignments.length,11);assert.equal(new Set(x.shared.assignments.map(a=>a.id)).size,11);assert.equal(x.shared.deepZones,3);assert(x.rpo.pass&&x.work.steps.length);count++;}assert.equal(count,144);});

test('the same adjustment receives different guidance in short and long yardage',()=>{assert.match(evaluatePreview({situation:'short'}).fitAdvice,/fits this scenario/);assert.match(evaluatePreview({situation:'long'}).fitAdvice,/Do not prioritize/);});
